import re

_SEGMENT = re.compile(r"\A(0|[1-9][0-9]{0,2})\Z")  # \Z, not $: "$" also matches before a final newline
_PREFIX = re.compile(r"\A(0|[1-9][0-9]?)\Z")
MAX_IP = (1 << 32) - 1


def _parse_ip(text):
    segments = text.split(".")
    if len(segments) != 4:
        raise ValueError(f"expected 4 dot-separated segments, got {text!r}")
    value = 0
    for segment in segments:
        if not _SEGMENT.match(segment) or int(segment) > 255:  # a pattern, not int(): int(" 7") is 7
            raise ValueError(f"bad segment {segment!r} in {text!r}")
        value = (value << 8) | int(segment)  # the leftmost segment is the most significant byte
    return value


def _parse(text):
    """Returns (start, first, last) for "a.b.c.d" or "a.b.c.d/prefix"."""
    ip_part, slash, prefix_part = text.partition("/")
    start = _parse_ip(ip_part)
    if not slash:
        return start, 0, MAX_IP
    if not _PREFIX.match(prefix_part) or int(prefix_part) > 32:
        raise ValueError(f"bad prefix {prefix_part!r}")
    host_bits = 32 - int(prefix_part)
    first = start >> host_bits << host_bits  # /0 shifts by 32, which a Python int handles fine
    return start, first, first + (1 << host_bits) - 1


def _format(value):
    return ".".join(str((value >> shift) & 0xFF) for shift in (24, 16, 8, 0))


class IPV4Iterator:
    def __init__(self, address, reverse=False, step=1):
        self._cursor, self._lo, self._hi = _parse(address)
        if step <= 0:
            raise ValueError(f"step must be positive, got {step}")
        self._delta = -step if reverse else step

    def __iter__(self):
        return self

    def __next__(self):
        if not self._lo <= self._cursor <= self._hi:  # a step may jump past an end without landing on it
            raise StopIteration
        result = _format(self._cursor)
        self._cursor += self._delta
        return result

    def next_batch(self, size):
        if size < 0:
            raise ValueError(f"size must be non-negative, got {size}")
        out = []
        for _ in range(size):
            try:
                out.append(next(self))
            except StopIteration:
                break
        return out

import torch
import torch.nn as nn

class MergeableLoRALinear(nn.Module):
    def __init__(self, in_features, out_features, rank, alpha=1.0):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.linear.weight.requires_grad_(False)
        self.linear.bias.requires_grad_(False)
        self.lora_A = nn.Parameter(torch.randn(rank, in_features) * 0.01)
        self.lora_B = nn.Parameter(torch.zeros(out_features, rank))
        self.scaling = alpha / rank
        self.merged = False

    def delta_weight(self):
        return self.lora_B @ self.lora_A * self.scaling

    @torch.no_grad()
    def merge(self):
        if self.merged:
            return
        self.linear.weight.add_(self.delta_weight())
        self.merged = True

    @torch.no_grad()
    def unmerge(self):
        if not self.merged:
            return
        self.linear.weight.sub_(self.delta_weight())
        self.merged = False

    def forward(self, x):
        if self.merged:
            return self.linear(x)
        return self.linear(x) + (x @ self.lora_A.T @ self.lora_B.T) * self.scaling

def pass_at_k(num_samples, num_correct, k):
    if not num_samples or len(num_samples) != len(num_correct):
        raise ValueError("need one correct count per problem")
    if k < 1:
        raise ValueError("k must be at least 1")
    total = 0.0
    for n, c in zip(num_samples, num_correct):
        if n < k or c < 0 or c > n:
            raise ValueError("need k <= n and 0 <= c <= n")
        if n - c < k:
            total += 1.0
            continue
        miss = 1.0
        for i in range(n - c + 1, n + 1):
            miss *= 1.0 - k / i
        total += 1.0 - miss
    return total / len(num_samples)

import torch


def per_token_logprobs(logits, input_ids):
    log_probs = torch.log_softmax(logits, dim=-1)
    return torch.gather(log_probs, dim=-1, index=input_ids.unsqueeze(-1)).squeeze(-1)

# Adapted from Schuture/OpenAI-Interview-Notes (code under the MIT License).
RANKS = "23456789TJQKA"  # the index is the rank's value
TYPE_NAMES = ["High Card", "Pair", "Flush", "Three of a Kind"]


def _key(cards):
    """One comparable tuple per hand: (type, tie-break), so tuple order is hand order."""
    ranks = sorted((RANKS.index(card[0]) for card in cards), reverse=True)
    if ranks[0] == ranks[2]:
        return (3, ranks[0])
    if len({card[1] for card in cards}) == 1:
        return (2, *ranks)
    if ranks[0] == ranks[1]:  # after sorting, a pair is at [0:2] or [1:3]
        return (1, ranks[0], ranks[2])
    if ranks[1] == ranks[2]:
        return (1, ranks[1], ranks[0])
    return (0, *ranks)


class PokerTable:
    def hand_type(self, cards):
        return TYPE_NAMES[_key(cards)[0]]

    def compare_hands(self, a, b):
        ka, kb = _key(a), _key(b)
        return (ka > kb) - (ka < kb)

    def rank_players(self, hands):
        keys = [_key(hand) for hand in hands]
        best = max(keys)
        return [i for i, k in enumerate(keys) if k == best]

    def start_round(self, deck, strategies):
        self._deck, self._strategies = deck, strategies
        self._hands = [[] for _ in strategies]
        self._folded = [False] * len(strategies)
        self._next_card = 0  # moves only when a card is dealt, so a fold costs no card
        self._calls = 0

    def is_over(self):
        return self._calls >= 3 * len(self._strategies)

    def deal_card(self):
        round_no, player = divmod(self._calls, len(self._strategies))
        self._calls += 1
        if round_no == 2 and self._strategies[player](list(self._hands[player])):
            self._folded[player] = True
            return f"Player {player} folds."
        card = self._deck[self._next_card]
        self._next_card += 1
        self._hands[player].append(card)
        return f"Player {player} is dealt {card}."

    def check_result(self):
        alive = [p for p, folded in enumerate(self._folded) if not folded]
        if not alive:
            return "No winner: all players folded."
        best = self.rank_players([self._hands[p] for p in alive])
        if len(best) == 1:
            return f"Winner: Player {alive[best[0]]}"
        return "Winner: Tie (Players " + ", ".join(str(alive[i]) for i in best) + ")"

import torch


def response_token_mask(prompt_lens, total_lens, max_len):
    if prompt_lens.shape != total_lens.shape:
        raise ValueError(
            f"shape mismatch: {tuple(prompt_lens.shape)} vs {tuple(total_lens.shape)}"
        )
    if not isinstance(max_len, int) or max_len <= 0:
        raise ValueError(f"max_len must be a positive integer, got {max_len!r}")
    if (prompt_lens < 0).any() or (total_lens < prompt_lens).any() or (total_lens > max_len).any():
        raise ValueError("every row must satisfy 0 <= prompt_lens <= total_lens <= max_len")
    positions = torch.arange(max_len, device=prompt_lens.device).unsqueeze(0)
    return (positions >= prompt_lens.unsqueeze(-1)) & (positions < total_lens.unsqueeze(-1))

import torch

def rloo_advantage(rewards, group_size):
    if rewards.ndim != 1 or group_size < 2 or rewards.numel() % group_size != 0:
        raise ValueError("rewards must be 1-D and group_size >= 2 must divide its length")
    grouped = rewards.reshape(-1, group_size)
    baseline = (grouped.sum(dim=1, keepdim=True) - grouped) / (group_size - 1)
    return (grouped - baseline).reshape(-1)

def my_softmax(x: torch.Tensor, dim: int = -1) -> torch.Tensor:
    x_max = x.max(dim=dim, keepdim=True).values
    e_x = torch.exp(x - x_max)
    return e_x / e_x.sum(dim=dim, keepdim=True)

def regularized_loss(data_loss, named_parameters, l1=0.0, l2=0.0):
    if l1 < 0 or l2 < 0:
        raise ValueError("regularization strengths must be non-negative")
    loss = data_loss
    for _name, weight in named_parameters:
        if weight.ndim < 2:
            continue
        loss = loss + l1 * weight.abs().sum() + 0.5 * l2 * (weight * weight).sum()
    return loss

import torch.utils.checkpoint as cp

def checkpoint_sequential(fns, x):
    for fn in fns:
        x = cp.checkpoint(fn, x, use_reentrant=False)
    return x

class MyAdam:
    def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8):
        self.params = list(params)
        self.lr = lr
        self.beta1, self.beta2 = betas
        self.eps = eps
        self.t = 0
        self.m = [torch.zeros_like(p) for p in self.params]
        self.v = [torch.zeros_like(p) for p in self.params]

    def step(self):
        self.t += 1
        with torch.no_grad():
            for i, p in enumerate(self.params):
                if p.grad is None:
                    continue
                self.m[i] = self.beta1 * self.m[i] + (1 - self.beta1) * p.grad
                self.v[i] = self.beta2 * self.v[i] + (1 - self.beta2) * p.grad ** 2
                m_hat = self.m[i] / (1 - self.beta1 ** self.t)
                v_hat = self.v[i] / (1 - self.beta2 ** self.t)
                p -= self.lr * m_hat / (torch.sqrt(v_hat) + self.eps)

    def zero_grad(self):
        for p in self.params:
            if p.grad is not None:
                p.grad.zero_()

def beam_search(log_prob_fn, start_token, max_len, beam_width, eos_token):
    beams = [(0.0, [start_token])]
    completed = []
    for _ in range(max_len):
        candidates = []
        for score, seq in beams:
            if seq[-1] == eos_token:
                completed.append((score, seq))
                continue
            log_probs = log_prob_fn(torch.tensor(seq))
            topk_lp, topk_idx = log_probs.topk(beam_width)
            for j in range(beam_width):
                candidates.append((score + topk_lp[j].item(), seq + [topk_idx[j].item()]))
        if not candidates:
            break
        candidates.sort(key=lambda x: x[0], reverse=True)
        beams = candidates[:beam_width]
    all_seqs = completed + beams
    all_seqs.sort(key=lambda x: x[0], reverse=True)
    return all_seqs[0][1]

