class LabelScheduler:
    def _invalid(self, t, m, h, k):
        if t <= 0 or m <= 0 or h <= 0:
            return None
        if k == 0:
            return []
        if k > t:  # a human can see each task once, so at most t assignments each
            return None
        return False

    def basic_schedule(self, t, m, h, k):
        early = self._invalid(t, m, h, k)
        if early is not False:
            return early
        # round r gives human u task (u + r) % t; k <= t rounds never repeat a task for one human
        return [((u + r) % t, 0, u) for r in range(k) for u in range(h)]

    def balanced_schedule(self, t, m, h, k):
        early = self._invalid(t, m, h, k)
        if early is not False:
            return early
        seen = [0] * t  # occurrences of each task so far; its c-th occurrence uses model c % m
        schedule = []
        for task, _, u in self.basic_schedule(t, m, h, k):
            schedule.append((task, seen[task] % m, u))
            seen[task] += 1
        return schedule

    def greedy_schedule(self, t, m, h, k):
        early = self._invalid(t, m, h, k)
        if early is not False:
            return early
        task_count = [[0] * m for _ in range(t)]
        human_count = [[0] * m for _ in range(h)]
        schedule = []
        for task, _, u in self.basic_schedule(t, m, h, k):
            model = min(range(m), key=lambda i: (task_count[task][i], human_count[u][i], i))
            task_count[task][model] += 1
            human_count[u][model] += 1
            schedule.append((task, model, u))
        return schedule

    def first_human_imbalance(self, schedule, m):
        counts = {}
        for p, (_, model, u) in enumerate(schedule, start=1):
            row = counts.setdefault(u, [0] * m)
            row[model] += 1
            if max(row) - min(row) > 1:  # only human u changed, so only u can newly break balance
                return p
        return None

def my_layer_norm(x, gamma, beta, eps=1e-5):
    mean = x.mean(dim=-1, keepdim=True)
    var = x.var(dim=-1, keepdim=True, unbiased=False)
    x_norm = (x - mean) / torch.sqrt(var + eps)
    return gamma * x_norm + beta

class SimpleLinear:
    def __init__(self, in_features: int, out_features: int):
        self.weight = torch.randn(out_features, in_features) * (1 / math.sqrt(in_features))
        self.weight.requires_grad_(True)
        self.bias = torch.zeros(out_features, requires_grad=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x @ self.weight.T + self.bias

import torch

MODES = ("token-mean", "seq-mean-token-mean", "seq-mean-token-sum", "seq-mean-token-sum-norm")

def aggregate_loss(per_token_loss, mask, mode):
    if mode not in MODES:
        raise ValueError(f"unknown mode {mode!r}")
    if per_token_loss.ndim != 2 or per_token_loss.shape != mask.shape:
        raise ValueError("per_token_loss and mask must share one (B, T) shape")
    mask = mask.bool()
    if not bool(mask.any()):
        raise ValueError("mask has no valid tokens")
    masked = torch.where(mask, per_token_loss, torch.zeros_like(per_token_loss))
    seq_sum = masked.sum(dim=1)
    seq_len = mask.sum(dim=1)
    if mode == "token-mean":
        return seq_sum.sum() / seq_len.sum()
    valid = seq_len > 0
    if mode == "seq-mean-token-mean":
        per_seq = seq_sum[valid] / seq_len[valid]
    elif mode == "seq-mean-token-sum":
        per_seq = seq_sum[valid]
    else:
        per_seq = seq_sum[valid] / mask.shape[1]
    return per_seq.mean()

import torch

def masked_perplexity(logprobs, mask):
    if logprobs.shape != mask.shape:
        raise ValueError("shape mismatch")
    valid = mask.bool()
    if not valid.any():
        raise ValueError("no valid tokens")
    return torch.exp(-logprobs[valid].mean())

