import copy

ADMIN = "admin"


class _File:
    def __init__(self, content, owner):
        self.content = content
        self.owner = owner


def _parts(path):
    """Components of a valid path, [] for the root, or None for an invalid path."""
    if not path.startswith("/"):
        return None
    parts = [p for p in path.split("/") if p]  # collapses repeated and trailing slashes
    return None if any(p in (".", "..") for p in parts) else parts


def _files(node, prefix):
    """(path, file) for every file under node; prefix is node's own path."""
    if isinstance(node, _File):
        yield prefix, node
        return
    for name, child in node.items():
        yield from _files(child, prefix.rstrip("/") + "/" + name)


class MemoryFS:
    def __init__(self):
        self._root = {}
        self._capacity = {}  # user -> capacity; admin is never here
        self._used = {}      # user -> bytes owned
        self._snapshots = {}

    # -- lookups ---------------------------------------------------------
    def _get(self, parts):
        node = self._root
        for p in parts:
            if not isinstance(node, dict) or p not in node:
                return None
            node = node[p]
        return node

    def _blocked(self, parts):
        """True if some ancestor of parts exists as a file."""
        node = self._root
        for p in parts[:-1]:
            node = node.get(p)
            if node is None:
                return False
            if isinstance(node, _File):
                return True
        return False

    def _parent(self, parts):
        node = self._root
        for p in parts[:-1]:
            node = node.setdefault(p, {})  # like mkdir -p; callers check _blocked first
        return node

    def _bill(self, owner, delta):
        if owner != ADMIN:
            self._used[owner] += delta

    # -- part 1 ----------------------------------------------------------
    def mkdir(self, path):
        parts = _parts(path)
        if parts is None:
            return False
        node = self._root
        for p in parts:
            if isinstance(node.get(p), _File):
                return False
            node = node.get(p, {})
        node = self._root
        for p in parts:
            node = node.setdefault(p, {})
        return True

    def write(self, path, content, owner=ADMIN):
        parts = _parts(path)
        if not parts or self._blocked(parts) or isinstance(self._get(parts), dict):
            return False
        if owner != ADMIN and owner not in self._capacity:
            return False
        old = self._get(parts)
        if old is not None and old.owner != owner:
            return False  # a file's owner never changes
        freed = len(old.content) if old is not None else 0
        if owner != ADMIN and self._used[owner] - freed + len(content) > self._capacity[owner]:
            return False
        if old is not None:
            self._bill(owner, -freed)
            old.content = content
        else:
            self._parent(parts)[parts[-1]] = _File(content, owner)
        self._bill(owner, len(content))
        return True

    def read(self, path):
        parts = _parts(path)
        node = None if parts is None else self._get(parts)
        return node.content if isinstance(node, _File) else None

    def ls(self, path):
        parts = _parts(path)
        node = None if parts is None else self._get(parts)
        return sorted(node) if isinstance(node, dict) else None

    # -- part 2 ----------------------------------------------------------
    def _transfer(self, src, dst, keep_source):
        sp, dp = _parts(src), _parts(dst)
        if sp is None or dp is None:
            return False
        node = self._get(sp)
        if node is None:
            return False
        shorter = min(len(sp), len(dp))
        if sp[:shorter] == dp[:shorter]:
            return False  # same path, or one inside the other
        if self._blocked(dp):
            return False
        target = self._get(dp)
        if target is not None and isinstance(target, _File) != isinstance(node, _File):
            return False
        if isinstance(target, _File) and target.owner != node.owner:
            return False
        moved = copy.deepcopy(node) if keep_source else node
        delta = {}
        if target is not None:
            for _, f in _files(target, "/"):
                delta[f.owner] = delta.get(f.owner, 0) - len(f.content)  # overwritten files free their bytes
        if keep_source:
            for _, f in _files(moved, "/"):
                delta[f.owner] = delta.get(f.owner, 0) + len(f.content)
            for owner, change in delta.items():
                if owner != ADMIN and change > 0 and self._used[owner] + change > self._capacity[owner]:
                    return False  # all or nothing
        else:
            del self._get(sp[:-1])[sp[-1]]
        for owner, change in delta.items():
            self._bill(owner, change)
        self._parent(dp)[dp[-1]] = moved
        return True

    def mv(self, src, dst):
        return self._transfer(src, dst, keep_source=False)

    def cp(self, src, dst):
        return self._transfer(src, dst, keep_source=True)

    def rm(self, path):
        parts = _parts(path)
        if not parts:
            return False  # invalid, or the root
        node = self._get(parts)
        if node is None:
            return False
        for _, f in _files(node, "/"):
            self._bill(f.owner, -len(f.content))
        del self._get(parts[:-1])[parts[-1]]
        return True

    def size(self, path):
        parts = _parts(path)
        node = None if parts is None else self._get(parts)
        if node is None:
            return None
        return sum(len(f.content) for _, f in _files(node, "/"))

    # -- part 3 ----------------------------------------------------------
    def add_user(self, user_id, capacity):
        if user_id == ADMIN or user_id in self._capacity or capacity < 0:
            return False
        self._capacity[user_id], self._used[user_id] = capacity, 0
        return True

    def update_capacity(self, user_id, capacity):
        if user_id not in self._capacity or capacity < 0:
            return None
        self._capacity[user_id] = capacity
        owned = [(path, f) for path, f in _files(self._root, "/") if f.owner == user_id]
        owned.sort(key=lambda item: (-len(item[1].content), item[0]))  # largest first, then path order
        evicted = 0
        for path, _ in owned:
            if self._used[user_id] <= capacity:
                break
            self.rm(path)
            evicted += 1
        return evicted

    # -- part 4 ----------------------------------------------------------
    def snapshot(self, snapshot_id):
        if snapshot_id in self._snapshots:
            return False
        self._snapshots[snapshot_id] = copy.deepcopy((self._root, self._capacity, self._used))
        return True

    def restore(self, snapshot_id):
        if snapshot_id not in self._snapshots:
            return False
        self._root, self._capacity, self._used = copy.deepcopy(self._snapshots[snapshot_id])  # the snapshot stays intact
        return True

class SwiGLUMLP(nn.Module):
    def __init__(self, d_model, d_ff):
        super().__init__()
        self.gate_proj = nn.Linear(d_model, d_ff)
        self.up_proj = nn.Linear(d_model, d_ff)
        self.down_proj = nn.Linear(d_ff, d_model)

    def forward(self, x):
        gate = self.gate_proj(x)
        silu_gate = gate * torch.sigmoid(gate)
        return self.down_proj(silu_gate * self.up_proj(x))

def noisy_topk_route(clean_logits, noise, noise_std, k):
    if clean_logits.ndim != 2 or not isinstance(noise, torch.Tensor) or noise.shape != clean_logits.shape:
        raise ValueError("clean_logits and noise must be matching (tokens, num_experts) tensors")
    if not clean_logits.is_floating_point():
        raise ValueError("clean_logits must be floating point")
    num_experts = clean_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or k < 1 or k > num_experts:
        raise ValueError("k must be an integer in [1, num_experts]")
    if noise_std < 0:
        raise ValueError("noise_std must be non-negative")
    noisy = clean_logits + noise_std * noise
    probs = torch.softmax(noisy, dim=-1)
    weights, indices = torch.topk(probs, k, dim=-1)
    weights = weights / weights.sum(-1, keepdim=True)
    return indices, weights

def router_z_loss(router_logits):
    if not isinstance(router_logits, torch.Tensor) or router_logits.ndim != 2:
        raise ValueError("router_logits must be a (tokens, num_experts) tensor")
    if not router_logits.is_floating_point():
        raise ValueError("router_logits must be floating point")
    log_partition = torch.logsumexp(router_logits, dim=-1)
    return log_partition.square().mean()

def shared_routed_moe(x, expert_indices, expert_weights, routed_experts, shared_experts):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and routed route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("routed route tensors must align with tokens and indices must be long")
    if not routed_experts:
        raise ValueError("at least one routed expert is required")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(routed_experts)):
        raise ValueError("routed expert index out of range")
    routed_out = torch.zeros_like(x)
    routes = [[] for _ in routed_experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            routes[int(expert_indices[token, slot])].append((token, slot))
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = routed_experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        routed_out.index_add_(0, token_ids, expert_output * route_weights)
    shared_out = torch.zeros_like(x)
    for shared in shared_experts:
        shared_out = shared_out + shared(x)
    return routed_out + shared_out

def moe_topk_router(router_logits, k):
    if router_logits.ndim != 2:
        raise ValueError("router_logits must have shape (tokens, experts)")
    num_experts = router_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or not 1 <= k <= num_experts:
        raise ValueError("k must select between one and all experts")
    probabilities = torch.softmax(router_logits, dim=-1)
    weights, indices = torch.topk(probabilities, k, dim=-1)
    weights = weights / weights.sum(dim=-1, keepdim=True)
    return indices, weights

ELEMENTS = ("Ember", "Tide", "Bramble", "Spark")
BEATS = {"Ember": "Bramble", "Bramble": "Tide", "Tide": "Spark", "Spark": "Ember"}


class Monster:
    def __init__(self, name, hp, attack, element=None):
        if element is not None and element not in ELEMENTS:
            raise ValueError(f"unknown element: {element!r}")
        self.name, self.hp, self.attack, self.element = name, hp, attack, element

    def is_alive(self):
        return self.hp > 0

    def multiplier(self, defender):
        """The multiplier against defender, or None when one of the two has no element."""
        if self.element is None or defender.element is None:
            return None
        if BEATS[self.element] == defender.element:
            return 2
        if BEATS[defender.element] == self.element:
            return 0.5
        return 1

    def damage_to(self, defender):
        return max(1, int(self.attack * (self.multiplier(defender) or 1)))


class Team:
    def __init__(self, name, monsters):
        self.name = name
        self.monsters = [Monster(*spec) for spec in monsters]

    def alive(self):
        return [m for m in self.monsters if m.is_alive()]

    def is_beaten(self):
        return not self.alive()

    def attacker_against(self, defender, smart):
        alive = self.alive()
        if not smart:
            return alive[0]
        return max(alive, key=lambda m: m.damage_to(defender))  # max keeps the first on a tie


def run_battle(team_a, team_b, smart=False):
    attacking, defending = Team(*team_a), Team(*team_b)
    log = [f"Match start: {attacking.name} takes on {defending.name}"]
    while True:
        defender = defending.alive()[0]
        attacker = attacking.attacker_against(defender, smart)
        damage = attacker.damage_to(defender)
        defender.hp -= damage
        multiplier = attacker.multiplier(defender)
        label = "" if multiplier is None else f" ({multiplier:g}x)"
        outcome = f"{defender.name} has {defender.hp} HP left." if defender.is_alive() else f"{defender.name} is defeated!"
        log.append(f"{attacker.name} hits {defender.name} for {damage} damage{label}. {outcome}")
        if defending.is_beaten():
            log.append(f"Match over: {attacking.name} wins!")
            return log
        attacking, defending = defending, attacking

