import math

import numpy as np


class EntropyMeter:
    def entropy(self, logits):
        x = np.asarray(logits, dtype=float)
        shifted = x - x.max()  # the largest term becomes exp(0) = 1, so nothing overflows
        log_z = math.log(np.exp(shifted).sum())
        log_p = shifted - log_z  # log p_i without ever dividing tiny numbers
        return float(max(0.0, -(np.exp(log_p) * log_p).sum()))

    def _update(self, state, block):
        """Folds one block into (m, s, v): s = sum exp(x - m), v = sum exp(x - m) * (x - m)."""
        block = np.asarray(block, dtype=float)
        if block.size == 0:
            return state
        m, s, v = state
        new_m = max(m, float(block.max()))
        if s:  # rescale the old sums to the new maximum
            scale, delta = math.exp(m - new_m), m - new_m
            s, v = s * scale, (v + delta * s) * scale
        shifted = block - new_m
        e = np.exp(shifted)
        return new_m, s + float(e.sum()), v + float((e * shifted).sum())

    @staticmethod
    def _finish(state):
        _, s, v = state
        return max(0.0, math.log(s) - v / s)  # H = log Z - E[x - m]

    def entropy_blockwise(self, logits, block_size=2):
        x = np.asarray(logits, dtype=float)
        state = (-math.inf, 0.0, 0.0)
        for start in range(0, len(x), block_size):
            state = self._update(state, x[start:start + block_size])  # a view, not a copy
        return self._finish(state)

    def entropy_online(self, blocks):
        state = (-math.inf, 0.0, 0.0)
        for block in blocks:
            state = self._update(state, block)
        return self._finish(state)

import re

_NAME = re.compile(r"[A-Z]+[0-9]+")
_TERM = r"(?:[A-Z]+[0-9]+|[0-9]{1,18})"
_FORMULA = re.compile(rf"=\s*{_TERM}(?:\s*[+-]\s*{_TERM})*\s*")
_TOKEN = re.compile(r"[A-Z]+[0-9]+|[0-9]+|[+-]")


class FormulaError(ValueError):
    pass


class CycleError(ValueError):
    pass


class Spreadsheet:
    def __init__(self):
        self._terms = {}    # name -> list of (sign, cell name or int); only formula cells
        self._literal = {}  # name -> int; only literal cells
        self._reads = {}    # name -> set of cells its formula reads
        self._readers = {}  # name -> set of cells whose formula reads it
        self._values = {}

    def _check_name(self, name):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise FormulaError(f"bad cell name: {name!r}")

    def _parse(self, value):
        if type(value) is int:
            return None
        if not isinstance(value, str) or not _FORMULA.fullmatch(value):
            raise FormulaError(f"bad value: {value!r}")
        terms, sign = [], 1
        for token in _TOKEN.findall(value[1:]):
            if token in "+-":
                sign = 1 if token == "+" else -1
            else:
                terms.append((sign, token if token[0].isalpha() else int(token)))
        return terms

    def _reaches(self, start, goal):
        stack, seen = [start], set()
        while stack:
            cell = stack.pop()
            if cell == goal:
                return True
            if cell not in seen:
                seen.add(cell)
                stack.extend(self._reads.get(cell, ()))
        return False

    def set(self, name, value):
        self._check_name(name)
        terms = self._parse(value)
        reads = {t for _, t in terms if isinstance(t, str)} if terms is not None else set()
        if any(self._reaches(cell, name) for cell in reads):
            raise CycleError(f"{name} would depend on itself")
        for cell in self._reads.pop(name, ()):
            self._readers[cell].discard(name)
        for cell in reads:
            self._readers.setdefault(cell, set()).add(name)
        self._terms.pop(name, None)
        self._literal.pop(name, None)
        if terms is None:
            self._literal[name] = value
        else:
            self._terms[name] = terms
            self._reads[name] = reads
        self._recompute(name)

    def get(self, name):
        self._check_name(name)
        return self._values.get(name, 0)

    def _recompute(self, start):
        # Every cell the change reaches, evaluated once each in dependency order.
        order, seen = [], set()

        def visit(cell):
            if cell in seen:
                return
            seen.add(cell)
            for reader in self._readers.get(cell, ()):
                visit(reader)
            order.append(cell)

        visit(start)
        for cell in reversed(order):
            if cell in self._literal:
                self._values[cell] = self._literal[cell]
            elif cell in self._terms:
                self._values[cell] = sum(
                    sign * (self._values.get(t, 0) if isinstance(t, str) else t)
                    for sign, t in self._terms[cell]
                )

class SSEDecoder:
    def __init__(self):
        self._line = bytearray()
        self._skip_lf = False
        self._event = None
        self._data = []
        self._last_id = None
        self._retry = None
        self._pending = False
        self.done = False

    def feed(self, chunk):
        events = []
        for byte in chunk:
            if self.done:
                break
            if self._skip_lf:
                self._skip_lf = False
                if byte == 10:
                    continue
            if byte != 10 and byte != 13:
                self._line.append(byte)
                continue
            self._skip_lf = byte == 13
            line = self._line.decode("utf-8")
            self._line.clear()
            event = self._decode(line)
            if event is None:
                continue
            if event["data"].startswith("[DONE]"):
                self.done = True
            else:
                events.append(event)
        return events

    def _decode(self, line):
        if not line:
            if not self._pending:
                return None
            event = {"event": self._event, "data": "\n".join(self._data), "id": self._last_id, "retry": self._retry}
            self._event, self._data, self._retry, self._pending = None, [], None, False
            return event
        if line.startswith(":"):
            return None
        field, _, value = line.partition(":")
        if value.startswith(" "):
            value = value[1:]
        if field == "event":
            self._event = value
        elif field == "data":
            self._data.append(value)
        elif field == "id":
            if "\0" in value:
                return None
            self._last_id = value
        elif field == "retry":
            if not value or any(c not in "0123456789" for c in value):
                return None
            self._retry = int(value)
        else:
            return None
        self._pending = True
        return None

class StopStringStream:
    def __init__(self, stop, include_stop_str_in_output=False, min_tokens=0):
        self.stop = list(stop)
        self.include = include_stop_str_in_output
        self.min_tokens = min_tokens
        self.hold = max(len(s) for s in self.stop) - 1 if self.stop and not self.include else 0
        self.output_text = ""
        self.num_tokens = 0
        self._returned = 0

    def update(self, new_texts):
        if not new_texts:
            return None
        check_from = len(self.output_text)
        for text in new_texts:
            self.output_text += text
            self.num_tokens += 1
            if self.min_tokens and self.num_tokens <= self.min_tokens:
                check_from = len(self.output_text)
        if not self.stop or self.num_tokens <= self.min_tokens:
            return None

        new_chars = len(self.output_text) - check_from
        if not new_chars:
            return None
        best, best_index, best_end = None, 0, None
        for s in self.stop:
            index = self.output_text.find(s, max(0, len(self.output_text) - new_chars - len(s) + 1))
            if index == -1:
                continue
            end = index + len(s)
            if best_end is None or end < best_end:
                best, best_index, best_end = s, index, end
        if best is None:
            return None
        self.output_text = self.output_text[:best_end] if self.include else self.output_text[:best_index]
        return best

    def get_next_output_text(self, finished):
        limit = len(self.output_text) - (0 if finished else self.hold)
        if self._returned < limit:
            text = self.output_text[self._returned:limit]
            self._returned = limit
            return text
        return ""

