class _Worker:
    def __init__(self, position, rate):
        self.position = position
        self.rate = rate
        self.pending = None  # (position, rate) waiting for the next clock_in
        self.open = None     # (start, rate) of the session in progress
        self.sessions = []   # closed sessions as (start, end, rate)
        self.total = 0


def _overlap(a, b, c, d):
    return max(0, min(b, d) - max(a, c))


class Timesheet:
    def __init__(self):
        self._workers = {}
        self._periods = []  # double-pay periods as given
        self._union = []    # their sorted, merged union, rebuilt when a period is added

    def add_worker(self, worker_id, position, hourly_rate):
        if worker_id in self._workers:
            return False
        self._workers[worker_id] = _Worker(position, hourly_rate)
        return True

    def clock_in(self, worker_id, timestamp):
        worker = self._workers.get(worker_id)
        if worker is None or worker.open is not None:
            return False
        if worker.pending is not None:  # a promotion starts with the next session, never inside one
            worker.position, worker.rate = worker.pending
            worker.pending = None
        worker.open = (timestamp, worker.rate)
        return True

    def clock_out(self, worker_id, timestamp):
        worker = self._workers.get(worker_id)
        if worker is None or worker.open is None:
            return False
        start, rate = worker.open
        worker.sessions.append((start, timestamp, rate))
        worker.total += timestamp - start
        worker.open = None
        return True

    def get_total_work_time(self, worker_id):
        worker = self._workers.get(worker_id)
        return None if worker is None else worker.total

    def top_k_workers(self, k):
        ranked = sorted(self._workers, key=lambda wid: (-self._workers[wid].total, wid))
        return ranked[:k]

    def set_promotion(self, worker_id, new_position, new_hourly_rate):
        worker = self._workers.get(worker_id)
        if worker is None:
            return False
        worker.pending = (new_position, new_hourly_rate)  # replaces any earlier pending promotion
        return True

    def get_position(self, worker_id):
        worker = self._workers.get(worker_id)
        return None if worker is None else worker.position

    def calculate_pay(self, worker_id, start, end):
        worker = self._workers.get(worker_id)
        if worker is None:
            return None
        sessions = list(worker.sessions)
        if worker.open is not None:
            sessions.append((worker.open[0], end, worker.open[1]))  # still running through the window
        pay = 0
        for a, b, rate in sessions:
            lo, hi = max(a, start), min(b, end)
            if lo >= hi:
                continue
            doubled = sum(_overlap(lo, hi, p, q) for p, q in self._union)
            pay += (hi - lo) * rate + doubled * rate
        return pay

    def set_double_pay(self, start, end):
        if end <= start:
            return
        self._periods.append((start, end))
        merged = []
        for p, q in sorted(self._periods):
            if merged and p <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], q)  # overlapping or touching periods join
            else:
                merged.append([p, q])
        self._union = [tuple(m) for m in merged]

class ToolRegistry:
    _TYPE_NAMES = {
        str: "string", int: "integer", float: "number",
        bool: "boolean", list: "array", dict: "object",
    }

    def __init__(self):
        self._tools = {}

    def register(self, tool):
        if not isinstance(tool.name, str) or not tool.name:
            raise ValueError("tool name must be non-empty")
        if tool.name in self._tools:
            raise ValueError(f"duplicate tool: {tool.name}")
        if not isinstance(tool.description, str) or not tool.description:
            raise ValueError("tool description must be non-empty")
        if not isinstance(tool.argument_schema, dict):
            raise TypeError("argument schema must be a dictionary")
        if any(not isinstance(name, str) or declared not in self._TYPE_NAMES
               for name, declared in tool.argument_schema.items()):
            raise TypeError("argument schema contains an unsupported entry")
        self._tools[tool.name] = tool

    def describe(self):
        return [
            {
                "name": tool.name,
                "description": tool.description,
                "parameters": {
                    name: self._TYPE_NAMES[declared]
                    for name, declared in tool.argument_schema.items()
                },
            }
            for tool in self._tools.values()
        ]

    def invoke(self, name, arguments, idempotency_key=None):
        if name not in self._tools:
            raise KeyError(f"unknown tool: {name}")
        if not isinstance(arguments, dict):
            raise TypeError("arguments must be a dictionary")
        tool = self._tools[name]
        if set(arguments) != set(tool.argument_schema):
            raise ValueError("argument names do not match the schema")
        for argument, declared in tool.argument_schema.items():
            if type(arguments[argument]) is not declared:
                raise TypeError(f"invalid type for {argument}")
        return tool.invoke(arguments, idempotency_key=idempotency_key)

import math
import torch

def truncated_is_weights(train_logprobs, rollout_logprobs, mask, cap=2.0, level="token"):
    if cap <= 0:
        raise ValueError("cap must be positive")
    if level not in ("token", "sequence"):
        raise ValueError(f"unknown level {level!r}")
    if train_logprobs.ndim != 2 or train_logprobs.shape != rollout_logprobs.shape or train_logprobs.shape != mask.shape:
        raise ValueError("inputs must share one (B, T) shape")
    mask = mask.bool()
    delta = torch.where(mask, train_logprobs.detach() - rollout_logprobs.detach(), torch.zeros_like(train_logprobs))
    if level == "sequence":
        delta = delta.sum(dim=1, keepdim=True).expand_as(delta)
    weights = torch.exp(torch.clamp(delta, max=math.log(cap)))
    return torch.where(mask, weights, torch.zeros_like(weights))

