import asyncio
from collections import deque
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait
from urllib.parse import urlparse


def _normalise(url):
    return url.split("#", 1)[0]  # only the fragment goes; scheme, host, port and path stay


class WebCrawler:
    def _new_links(self, links, host, seen):
        """The normalised in-scope links not seen before; marks them seen."""
        fresh = []
        for link in links:
            url = _normalise(link)
            if urlparse(url).hostname == host and url not in seen:
                seen.add(url)
                fresh.append(url)
        return fresh

    @staticmethod
    def _fetch(parser, url):
        try:
            return parser.get_urls(url)
        except Exception:  # a failed page still counts as crawled; it just has no links
            return []

    def crawl(self, start_url, html_parser):
        start = _normalise(start_url)
        host, seen, queue = urlparse(start).hostname, {start}, deque([start])
        while queue:
            url = queue.popleft()
            queue.extend(self._new_links(self._fetch(html_parser, url), host, seen))
        return sorted(seen)

    def crawl_concurrent(self, start_url, html_parser, max_workers=8):
        start = _normalise(start_url)
        host, seen = urlparse(start).hostname, {start}
        # only this thread touches `seen`; workers just fetch, so no lock is needed
        with ThreadPoolExecutor(max_workers=max_workers) as pool:
            pending = {pool.submit(self._fetch, html_parser, start)}
            while pending:
                done, pending = wait(pending, return_when=FIRST_COMPLETED)
                for future in done:
                    for url in self._new_links(future.result(), host, seen):
                        pending.add(pool.submit(self._fetch, html_parser, url))
        return sorted(seen)

    async def crawl_async(self, start_url, html_parser, concurrency=8):
        start = _normalise(start_url)
        host, seen = urlparse(start).hostname, {start}
        gate = asyncio.Semaphore(concurrency)
        tasks = set()

        async def visit(url):
            async with gate:  # at most `concurrency` blocking calls in flight
                links = await asyncio.to_thread(self._fetch, html_parser, url)
            for new in self._new_links(links, host, seen):
                tasks.add(asyncio.create_task(visit(new)))

        tasks.add(asyncio.create_task(visit(start)))
        while tasks:
            done, _ = await asyncio.wait(tasks)
            tasks.difference_update(done)
        return sorted(seen)

def finalize_agent_rollout(response_ids, response_mask, rollout_log_probs, reward, max_response_length, overlong_penalty):
    import math
    import torch

    tensors = (response_ids, response_mask, rollout_log_probs)
    if any(not isinstance(tensor, torch.Tensor) or tensor.ndim != 1 for tensor in tensors):
        raise ValueError("response tensors must be one-dimensional tensors")
    if response_ids.numel() == 0:
        raise ValueError("response tensors must be non-empty")
    if not (response_ids.numel() == response_mask.numel() == rollout_log_probs.numel()):
        raise ValueError("response tensors must have the same length")
    if not (response_ids.device == response_mask.device == rollout_log_probs.device):
        raise ValueError("response tensors must be on the same device")
    if response_ids.dtype == torch.bool or torch.is_floating_point(response_ids) or torch.is_complex(response_ids):
        raise ValueError("response_ids must use an integer dtype")
    if response_mask.dtype != torch.bool:
        raise ValueError("response_mask must use boolean dtype")
    if not rollout_log_probs.dtype.is_floating_point:
        raise ValueError("rollout_log_probs must use a floating-point dtype")
    if not isinstance(max_response_length, int) or isinstance(max_response_length, bool) or max_response_length < 1:
        raise ValueError("max_response_length must be a positive integer")
    penalty = float(overlong_penalty)
    if math.isnan(penalty) or penalty < 0:
        raise ValueError("overlong_penalty must be non-negative")

    original_length = response_ids.numel()
    truncated = original_length > max_response_length
    kept = min(original_length, max_response_length)
    kept_ids = response_ids[:kept].clone()
    kept_mask = response_mask[:kept].clone()
    kept_log_probs = rollout_log_probs[:kept].clone()

    effective_reward = float(reward) - (penalty if truncated else 0.0)
    token_rewards = torch.zeros_like(kept_log_probs)
    token_rewards[-1] = effective_reward

    return {
        "response_ids": kept_ids,
        "response_mask": kept_mask,
        "rollout_log_probs": kept_log_probs,
        "token_rewards": token_rewards,
        "truncated": truncated,
    }

