class ConfigError(Exception):
    pass


class ConfigNotFoundError(ConfigError):
    pass


class ConfigCycleError(ConfigError):
    pass


class OverrideSyntaxError(ConfigError):
    pass


class OverrideKeyError(ConfigError):
    pass


