from functools import lru_cache

MOD = 10**9 + 7


class JumpGrid:
    def __init__(self, board):
        self._board = [list(row) for row in board]  # a private copy, so later changes to board do not leak in
        self._n = len(board)
        self._m = len(board[0])

    def _moves(self, i, j, jumps):
        """(next row, next column, jumps left) for every legal move from (i, j), in cell order."""
        if i + 1 < self._n:
            for c in (j - 1, j, j + 1):
                if 0 <= c < self._m:
                    yield i + 1, c, jumps
        if jumps and i + 2 < self._n:
            yield i + 2, j, jumps - 1

    def _table(self, k):
        """best[i][j][b]: the largest base score from (i, j) to the last row with b jumps left."""
        n, m, board = self._n, self._m, self._board
        best = [[[0] * (k + 1) for _ in range(m)] for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(m):
                for b in range(k + 1):
                    if i == n - 1:
                        best[i][j][b] = board[i][j]
                    else:  # every row above the last has at least one step down
                        best[i][j][b] = board[i][j] + max(best[r][c][left] for r, c, left in self._moves(i, j, b))
        return best

    def _cap(self, k):
        return min(k, (self._n - 1) // 2)  # no path can use more jumps than this

    def max_score(self, p, k):
        k = self._cap(k)
        return self._table(k)[0][p][k]

    def optimal_path(self, p, k):
        k = self._cap(k)
        best = self._table(k)
        i, j, b = 0, p, k
        path = [(0, p)]
        while i < self._n - 1:
            want = best[i][j][b] - self._board[i][j]
            # moves come in (row, column) order, so the first optimal one keeps the path smallest
            i, j, b = next(move for move in self._moves(i, j, b) if best[move[0]][move[1]][move[2]] == want)
            path.append((i, j))
        return path

    def count_optimal_paths(self, p, k):
        k = self._cap(k)
        best = self._table(k)
        n, m = self._n, self._m
        count = [[[1] * (k + 1) for _ in range(m)] for _ in range(n)]
        for i in range(n - 2, -1, -1):
            for j in range(m):
                for b in range(k + 1):
                    want = best[i][j][b] - self._board[i][j]
                    count[i][j][b] = sum(count[r][c][left] for r, c, left in self._moves(i, j, b)
                                         if best[r][c][left] == want) % MOD
        return count[0][p][k]

    def max_score_with_bonuses(self, p, k, x, y):
        k = self._cap(k)
        board, last = self._board, self._n - 1

        @lru_cache(maxsize=None)
        def score(i, j, b, before):
            """Best score from (i, j) on, counting board[i][j]; before is the value visited just before it."""
            here = board[i][j]
            if i == last:
                return here
            options = []
            for r, c, left in self._moves(i, j, b):
                nxt = board[r][c]
                bonus = (x if here == nxt else 0) + (y if before is not None and before < here < nxt else 0)
                options.append(bonus + score(r, c, left, here))
            return here + max(options)

        result = score(0, p, k, None)
        score.cache_clear()
        return result

import json
import os
import struct
import threading
import zlib
from collections import OrderedDict

_HEADER = struct.Struct(">II")  # payload length, crc32 of the payload


def _encode(value):
    # JSON has no tuple, so tag containers to bring keys back exactly.
    if isinstance(value, tuple):
        return {"t": [_encode(v) for v in value]}
    if isinstance(value, list):
        return {"l": [_encode(v) for v in value]}
    if isinstance(value, dict):
        return {"d": {k: _encode(v) for k, v in value.items()}}
    return value


def _decode(value):
    if isinstance(value, dict):
        (tag, inner), = value.items()
        if tag == "t":
            return tuple(_decode(v) for v in inner)
        if tag == "l":
            return [_decode(v) for v in inner]
        return {k: _decode(v) for k, v in inner.items()}
    return value


class _Flight:
    def __init__(self):
        self.done = threading.Event()
        self.result = None
        self.error = None


class Memoize:
    def __init__(self, func, capacity, path=None):
        self.func = func
        self.capacity = capacity
        self.cache = OrderedDict()
        self.hits = 0
        self.misses = 0
        self.path = path
        self._lock = threading.Lock()
        self._flights = {}
        self._log = None
        if path is not None:
            self._recover()
            self._log = open(path, "ab")

    def generate_key(self, *args, **kwargs):
        return (args, tuple(sorted(kwargs.items())))

    def __call__(self, *args, **kwargs):
        key = self.generate_key(*args, **kwargs)
        with self._lock:
            if key in self.cache:
                self.hits += 1
                self.cache.move_to_end(key)
                self._append({"op": "touch", "key": _encode(key)})
                return self.cache[key]
            flight = self._flights.get(key)
            leader = flight is None
            if leader:
                flight = self._flights[key] = _Flight()
                self.misses += 1
        if not leader:
            flight.done.wait()
            if flight.error is not None:
                raise flight.error
            return flight.result
        try:
            result = self.func(*args, **kwargs)
        except BaseException as error:
            with self._lock:
                del self._flights[key]
            flight.error = error
            flight.done.set()
            raise
        with self._lock:
            self._put(key, result)
            self._append({"op": "put", "key": _encode(key), "value": _encode(result)})
            del self._flights[key]
        flight.result = result
        flight.done.set()
        return result

    def compact(self):
        if self.path is None:
            return
        with self._lock:
            tmp = self.path + ".compact"
            with open(tmp, "wb") as out:
                for key, value in self.cache.items():
                    out.write(self._frame({"op": "put", "key": _encode(key), "value": _encode(value)}))
                out.flush()
                os.fsync(out.fileno())
            self._log.close()
            os.replace(tmp, self.path)
            self._log = open(self.path, "ab")

    def _put(self, key, value):
        self.cache[key] = value
        self.cache.move_to_end(key)
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    @staticmethod
    def _frame(record):
        payload = json.dumps(record, separators=(",", ":")).encode()
        return _HEADER.pack(len(payload), zlib.crc32(payload)) + payload

    def _append(self, record):
        if self._log is None:
            return
        self._log.write(self._frame(record))
        self._log.flush()
        os.fsync(self._log.fileno())

    def _recover(self):
        if not os.path.exists(self.path):
            return
        with open(self.path, "rb") as fh:
            data = fh.read()
        offset = 0
        while offset + _HEADER.size <= len(data):
            length, crc = _HEADER.unpack_from(data, offset)
            payload = data[offset + _HEADER.size: offset + _HEADER.size + length]
            if len(payload) < length or zlib.crc32(payload) != crc:
                break
            try:
                record = json.loads(payload)
                key = _decode(record["key"])
            except (ValueError, KeyError, TypeError):
                break
            if record["op"] == "put":
                self._put(key, _decode(record["value"]))
            elif key in self.cache:
                self.cache.move_to_end(key)
            offset += _HEADER.size + length
        if offset < len(data):
            with open(self.path, "r+b") as fh:
                fh.truncate(offset)

